  "prediction_basis_card_ids": ["C18", "C08", "C10", "C33", "C44", "C45"],
  "claims": [
    {
      "claim": "DHA, a non-aromatic rigid oxygenated polycyclic lactone with no basic center, has absolute oral bioavailability of 45% (95% CI 34–56) in healthy volunteers, indicating this structural class can exceed the 20% threshold despite solubility limitations.",
      "card_ids": ["C18", "C24"]
    },
    {
      "claim": "Hydrocortisone, a polar non-aromatic steroid, has oral bioavailability of 56–96% after oral administration, showing that rigid polar polycycles can be well absorbed.",
      "card_ids": ["C08", "C23", "C40", "C45"]
    },
    {
      "claim": "Etoposide, a high-TPSA glycosidic lactone, has oral bioavailability of 48% ± 18% after oral capsules vs IV, supporting that high polarity does not preclude F >=20%.",
      "card_ids": ["C33", "C22"]
    },
    {
      "claim": "9-AC, a lactone-containing molecule, has oral bioavailability of 27–49% in patients, supporting that lactone-containing polar molecules can exceed 20%.",
      "card_ids": ["C10", "C21", "C44"]
    },
    {
      "claim": "Idarubicin, a polar anthracycline, has mean oral bioavailability of 23.7–25% (individual range ~9–39%), still above the 20% threshold despite high polarity and variability.",
      "card_ids": ["C35", "C46"]
    },
    {
      "claim": "The low-F records (omadacycline 0.6% fed high-fat; CGP 43371 9%; moxidectin alpaca 10.6%) come from structurally dissimilar aromatic/basic or species-specific contexts and are not transferable to this neutral polycyclic lactone.",
      "card_ids": ["C09", "C31", "C36"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C32", "C33", "C34", "C35", "C38", "C39", "C40", "C41", "C44", "C45", "C46"]
    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C37", "C42", "C43"]
    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "low",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C36"]
    }
  ],
  "evidence_gaps": [
    "No direct human absolute oral bioavailability measurement for the query molecule.",
    "No matched oral versus IV exposure data for the query.",
    "Structural similarity to reference contexts is qualitative; no numeric similarity score is available.",
    "Transporter/efflux or first-pass metabolism status of the query is unknown.",
    "Formulation and dose effects on query absorption are unknown.",
    "The query's very low logD (-1.37) and high TPSA (149) raise permeability concerns that are not directly resolved by reference contexts."
  ],
  "decision_summary": "Despite a negative physicochemical prior, transferable evidence from structurally related non-aromatic oxygenated polycycles (DHA 45%, hydrocortisone 56–96%, etoposide 48%, 9-AC 27–49%) supports F >=20%; low-F records are from structurally dissimilar or species-specific contexts, so low is not affirmatively supported."
}

